import { forwardRef, useRef, useState } from 'react'
import { AccessibilityInfo } from 'react-native'
import {
  type GetProps,
  type TamaguiElement,
  Text,
  View,
  XStack,
  isWeb,
  styled,
} from 'tamagui/unstyled'
import { type FieldControlProps, useFieldControl } from '../../hooks/useFieldControl'
import { useControllableState } from '../../hooks/useControllableState'
import { ariaState } from '../../utils/ariaState'
import { visuallyHidden } from '../../utils/visuallyHidden'
import { Chip } from '../chip/Chip'
import { fieldBoxStyle } from '../input/Input'
import { TagsInputText } from './TagsInputText'

export const TagsInputFrame = styled(XStack, {
  displayName: 'TagsInput',
  ...fieldBoxStyle,
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: '1-5',
  cursor: 'text',
  variants: {
    // The row of tags and the text box fits inside the field's height, so a
    // field with one row is as tall as an Input of the same size.
    size: {
      sm: {
        minHeight: '8',
        paddingHorizontal: '1',
        paddingVertical: '0-5',
      },
      md: {
        minHeight: '10',
        paddingHorizontal: '1-5',
        paddingVertical: '1',
      },
      lg: {
        minHeight: '12',
        paddingHorizontal: '2',
        paddingVertical: '1',
      },
    },
    focused: {
      true: {
        borderColor: 'ring hover:ring',
      },
    },
    invalid: {
      true: {
        borderColor: 'error hover:error',
      },
    },
    disabled: {
      true: { opacity: 0.5, cursor: 'not-allowed' },
    },
  } as const,
  defaultVariants: { size: 'md' },
})

const rowHeights = { sm: '6', md: '7', lg: '8' } as const
const fontSizes = { sm: '2', md: '2', lg: '3' } as const
// The text box's own inset, so its text and placeholder line up with an Input's.
const textInsets = { sm: '1-5', md: '1-5', lg: '2' } as const

export interface TagsInputLabels {
  /** Name of a tag's remove button. Default: "Remove {tag}". */
  remove: (tag: string) => string
  /** Announced when tags are added. Default: "Added {tags}". */
  added: (tags: string[]) => string
  /** Announced when a tag is removed. Default: "Removed {tag}". */
  removed: (tag: string) => string
}

const defaultLabels: TagsInputLabels = {
  remove: (tag) => `Remove ${tag}`,
  added: (tags) => `Added ${tags.join(', ')}`,
  removed: (tag) => `Removed ${tag}`,
}

type FrameProps = GetProps<typeof TagsInputFrame>

export interface TagsInputProps
  extends
    Omit<
      FrameProps,
      'children' | 'size' | 'focused' | 'invalid' | 'disabled' | keyof FieldControlProps
    >,
    FieldControlProps {
  /** The tags, in order (controlled). */
  value?: string[]
  /** Starting tags when uncontrolled. */
  defaultValue?: string[]
  /** Called with the new list when tags are added or removed. */
  onValueChange?: (value: string[]) => void
  placeholder?: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Characters that end a tag as you type them, besides Enter. Pasted text is
   * split at them. Default: `[',']`; `[]` leaves only Enter.
   */
  separators?: string[]
  /** Most tags allowed; more are refused. */
  max?: number
  /** Allow the same tag twice. Default: false. */
  allowDuplicates?: boolean
  /** Return false to refuse a tag; it stays in the text box to be fixed. */
  validate?: (tag: string, value: string[]) => boolean
  /** Add the typed text when the field loses focus. Default: true. */
  addOnBlur?: boolean
  /** Web: the field name each tag submits under in a native form. */
  name?: string
  /** Remove-button names and announcements, for translation. */
  labels?: Partial<TagsInputLabels>
}

const none: string[] = []
const defaultSeparators = [',']

const escape = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

type KeyEvent = {
  key: string
  preventDefault?: () => void
  nativeEvent?: { isComposing?: boolean }
}

/**
 * A text field that turns what you type into tags: Enter or a separator
 * (comma by default) adds one, each tag is a chip with a remove button, and
 * Backspace in the empty text box removes the last. Use Multi Select instead
 * when the choices come from a fixed list.
 */
export const TagsInput = forwardRef<TamaguiElement, TagsInputProps>(
  function TagsInput(tagsProps, ref) {
    const {
      value: valueProp,
      defaultValue = none,
      onValueChange,
      placeholder,
      size = 'md',
      separators = defaultSeparators,
      max,
      allowDuplicates = false,
      validate,
      addOnBlur = true,
      name,
      labels: labelsProp,
      invalid = false,
      disabled = false,
      id,
      'aria-label': ariaLabel,
      'aria-describedby': describedBy,
      'aria-required': required,
      accessibilityHint,
      ...props
    } = useFieldControl(tagsProps)
    const labels = { ...defaultLabels, ...labelsProp }
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const [text, setTextState] = useState('')
    // The text as of the last change: native can report one return key press
    // twice (key press and submit), and the second must not add the tag again.
    const textRef = useRef('')
    const setText = (next: string) => {
      textRef.current = next
      setTextState(next)
    }
    const [focused, setFocused] = useState(false)
    const [message, setMessage] = useState({ text: '', count: 0 })
    const inputRef = useRef<HTMLInputElement | null>(null)

    const announce = (next: string) => {
      if (isWeb) setMessage((current) => ({ text: next, count: current.count + 1 }))
      else AccessibilityInfo.announceForAccessibility(next)
    }

    /** Adds what it can and returns the tags it refused. */
    const add = (parts: string[]) => {
      const next = [...value]
      const added: string[] = []
      const refused: string[] = []
      for (const part of parts) {
        const tag = part.trim()
        if (!tag) continue
        const fits = max === undefined || next.length < max
        const fresh = allowDuplicates || !next.includes(tag)
        if (fits && fresh && (validate?.(tag, next) ?? true)) {
          next.push(tag)
          added.push(tag)
        } else {
          refused.push(tag)
        }
      }
      if (added.length) {
        setValue(next)
        announce(labels.added(added))
      }
      return refused
    }

    const commit = () => {
      const pending = textRef.current
      if (!pending.trim()) return false
      setText(add([pending]).length ? pending : '')
      return true
    }

    const remove = (index: number) => {
      const tag = value[index]
      if (tag === undefined) return
      setValue(value.filter((_, i) => i !== index))
      announce(labels.removed(tag))
    }

    const splitter = separators.length ? new RegExp(separators.map(escape).join('|')) : null

    const onChangeText = (input: string) => {
      const parts = splitter ? input.split(splitter) : [input]
      if (parts.length === 1) {
        // Space after a separator would only push the next tag along.
        setText(textRef.current || input.trim() ? input : '')
        return
      }
      // Typing adds one character at a time; more at once is a paste, and a
      // pasted list adds its last part too.
      const pasted = input.length - textRef.current.length > 1
      const rest = pasted ? '' : parts.pop()!.trimStart()
      const refused = add(parts)
      setText([...refused, rest].filter(Boolean).join(`${separators[0]} `))
    }

    const onKeyDown = (event: KeyEvent) => {
      // Enter that confirms an input method's composition (Chinese, Japanese) is not ours.
      if (event.nativeEvent?.isComposing) return
      if (event.key === 'Enter') {
        // An empty text box lets Enter through, so it can submit a form.
        if (commit()) event.preventDefault?.()
      } else if (event.key === 'Backspace' && !textRef.current && value.length) {
        remove(value.length - 1)
      }
    }

    const focusInput = (event: { target?: unknown }) => {
      if (disabled) return
      const target = event.target as Element | null | undefined
      if (isWeb && target?.closest?.('button')) return
      inputRef.current?.focus()
    }

    return (
      <TagsInputFrame
        ref={ref}
        size={size}
        focused={focused}
        invalid={invalid}
        disabled={disabled}
        {...props}
        // The ring an Input draws on focus (web only, like its focus-visible outline).
        {...(isWeb &&
          focused && {
            outlineColor: invalid ? 'error' : 'ring',
            outlineStyle: 'solid',
            outlineWidth: 2,
          })}
        onPress={focusInput}
        {...(isWeb
          ? {
              // Presses on the box and on remove buttons keep focus in the
              // text box, so its blur does not add half-typed text.
              onMouseDown: (event: { target: unknown; preventDefault: () => void }) => {
                if (event.target !== inputRef.current) event.preventDefault()
              },
            }
          : { accessible: false })}
      >
        {value.map((tag, index) => (
          <Chip
            key={`${index}-${tag}`}
            height={rowHeights[size]}
            disabled={disabled}
            onRemove={() => {
              remove(index)
              // The button is gone; the text box is the next place to work.
              if (isWeb) inputRef.current?.focus()
            }}
            removeLabel={labels.remove(tag)}
          >
            {tag}
          </Chip>
        ))}
        <TagsInputText
          ref={inputRef as never}
          id={id}
          aria-label={ariaLabel}
          aria-describedby={describedBy}
          aria-required={required}
          aria-invalid={invalid || undefined}
          aria-disabled={ariaState(disabled)}
          accessibilityHint={accessibilityHint}
          disabled={disabled}
          placeholder={placeholder}
          height={rowHeights[size]}
          paddingHorizontal={textInsets[size]}
          fontSize={fontSizes[size]}
          autoCapitalize="none"
          autoCorrect={false}
          // Return adds the tag and keeps the keyboard open.
          submitBehavior="submit"
          value={text}
          onChangeText={onChangeText}
          onKeyDown={onKeyDown as never}
          // Native: return arrives as a submit (web reads it in onKeyDown).
          {...(!isWeb && { onSubmitEditing: commit })}
          onFocus={() => setFocused(true)}
          onBlur={() => {
            setFocused(false)
            if (addOnBlur) commit()
          }}
        />
        {isWeb ? (
          <>
            <View role="status" aria-live="polite" {...visuallyHidden}>
              {message.text ? <Text key={message.count}>{message.text}</Text> : null}
            </View>
            {name
              ? value.map((tag, index) => (
                  <input key={`${index}-${tag}`} type="hidden" name={name} value={tag} />
                ))
              : null}
          </>
        ) : null}
      </TagsInputFrame>
    )
  },
)

import { Input as TamaguiInput, styled } from 'tamagui/unstyled'
import { textBoxStyle } from './textBoxStyle'

/** Web: Tamagui's Input, an `<input>` that hears its own key presses. */
export const TagsInputText = styled(TamaguiInput, {
  ...textBoxStyle,
  // The field draws the focus ring; `outline-style: auto` ignores width.
  outlineWidth: 'focus:0px focus-visible:0px',
  outlineStyle: 'focus:none focus-visible:none',
})

import { registerFocusable } from '@tamagui/focusable'
import { forwardRef, useEffect, useRef } from 'react'
import { TextInput, type TextInputProps } from 'react-native'
import {
  type GetProps,
  Text,
  View,
  createStyledHOC,
  styled,
  useComposedRefs,
} from 'tamagui/unstyled'
import { textBoxStyle } from './textBoxStyle'

type KeyHandler = (event: { key: string }) => void

interface KeyTextInputProps extends TextInputProps {
  id?: string
  disabled?: boolean
  onKey?: KeyHandler
}

// Tamagui drops `onKeyPress` from its styled components on native, its own
// Input included, so Backspace never reached Tags Input. This is React
// Native's TextInput with the handler under a name Tamagui passes on.
const KeyTextInput = forwardRef<TextInput, KeyTextInputProps>(function KeyTextInput(
  { id, disabled = false, onKey, ...props },
  ref,
) {
  const inputRef = useRef<TextInput>(null)
  const composedRef = useComposedRefs(ref, inputRef)
  // A Field's label focuses its control through Tamagui's registry, as Input's does.
  useEffect(() => {
    if (!id || disabled) return
    const focus = () => inputRef.current?.focus()
    return registerFocusable(id, { focus, focusAndSelect: focus })
  }, [id, disabled])
  return (
    <TextInput
      ref={composedRef}
      editable={!disabled}
      // Read the key now: React Native reuses the event.
      onKeyPress={onKey && ((event) => onKey({ key: event.nativeEvent.key }))}
      {...props}
    />
  )
})

const Box = styled(KeyTextInput, textBoxStyle, {
  isInput: true,
  accept: { placeholderTextColor: 'color' },
})

const Placeholder = styled(Text, {
  displayName: 'TagsInputPlaceholder',
  fontFamily: 'body',
  color: 'placeholder-color',
  pointerEvents: 'none',
})

/**
 * Native: takes `onKeyDown` like the web box, as a styled HOC that keeps it.
 * Android wraps a placeholder wider than the box onto a cut-off second line,
 * whatever the TextInput's props, so the box shows its own one-line copy and
 * keeps the real placeholder, transparent, for screen readers.
 */
export const TagsInputText = createStyledHOC(
  Box,
  (
    {
      onKeyDown,
      placeholder,
      height,
      paddingHorizontal,
      fontSize,
      ...props
    }: GetProps<typeof Box> & { onKeyDown?: KeyHandler },
    ref,
  ) => (
    <View flex={1} minWidth="20" height={height} justifyContent="center">
      <Box
        ref={ref}
        {...props}
        placeholderTextColor="transparent"
        position="absolute"
        top={0}
        right={0}
        bottom={0}
        left={0}
        height={height}
        paddingHorizontal={paddingHorizontal}
        fontSize={fontSize}
        placeholder={placeholder}
        onKey={onKeyDown}
      />
      {placeholder && !props.value ? (
        <Placeholder
          aria-hidden
          numberOfLines={1}
          paddingHorizontal={paddingHorizontal}
          fontSize={fontSize}
        >
          {placeholder}
        </Placeholder>
      ) : null}
    </View>
  ),
)

import { CheckIcon, IconDefaults, XIcon } from '@advui/icons'
import { type ReactNode, forwardRef } from 'react'
import { type GetProps, type TamaguiElement, Text, View, isWeb, styled } from 'tamagui/unstyled'
import { useControllableState } from '../../hooks/useControllableState'
import { useRipple } from '../../hooks/useRipple'
import { isTextContent } from '../../utils/isTextContent'
import { ariaState } from '../../utils/ariaState'
import { flatValue } from '../../utils/responsive'

const ChipFrame = styled(View, {
  displayName: 'Chip',
  flexDirection: 'row',
  alignItems: 'center',
  alignSelf: 'flex-start',
  gap: '1-5',
  height: '8',
  paddingHorizontal: '3',
  borderWidth: 1,
  borderColor: 'input',
  borderRadius: 'lg',
  backgroundColor: 'transparent',
  userSelect: 'none',
  variants: {
    interactive: {
      true: {
        cursor: 'pointer',
        backgroundColor: 'hover:accent press:accentHover',
        outlineColor: 'focus-visible:ring',
        outlineStyle: 'focus-visible:solid',
        outlineWidth: 'focus-visible:2px',
        outlineOffset: 'focus-visible:2px',
      },
    },
    // Material's selected filter chip: a filled tonal surface without a border.
    selected: {
      true: {
        backgroundColor: 'secondary hover:secondaryHover press:secondaryPress',
        borderColor: 'secondary',
      },
    },
    disabled: {
      true: { opacity: 0.5, pointerEvents: 'none', cursor: 'default' },
    },
  } as const,
})

type FrameProps = GetProps<typeof ChipFrame>

export interface ChipProps extends Omit<
  FrameProps,
  'interactive' | 'selected' | 'disabled' | 'children'
> {
  children: ReactNode
  /** Leading icon. A selected filter chip shows a check instead. */
  icon?: ReactNode
  /**
   * Makes it a filter chip that turns on and off (announced as pressed). Use
   * `defaultSelected` for uncontrolled use.
   */
  selected?: boolean
  defaultSelected?: boolean
  onSelectedChange?: (selected: boolean) => void
  /** Makes it an input chip with a remove button, e.g. a recipient. */
  onRemove?: () => void
  /** Accessible name of the remove button. Default: "Remove {children}". */
  removeLabel?: string
  disabled?: boolean
}

type LabelColor = 'foreground' | 'secondaryForeground'

const Label = ({ children, color }: { children: ReactNode; color: LabelColor }) =>
  isTextContent(children) ? (
    <Text
      fontFamily="body"
      fontSize="2"
      lineHeight="2"
      fontWeight="500"
      color={color}
      numberOfLines={1}
      userSelect="none"
    >
      {children}
    </Text>
  ) : (
    <>{children}</>
  )

/**
 * A compact element for a choice, a filter, an entered value or a suggested
 * action. Pass `selected` for a filter chip, `onRemove` for an input chip or
 * `onPress` for an action chip.
 */
export const Chip = forwardRef<TamaguiElement, ChipProps>(function Chip(
  {
    children,
    icon,
    selected: selectedProp,
    defaultSelected,
    onSelectedChange,
    onRemove,
    removeLabel,
    disabled = false,
    onPress,
    onPressIn,
    onPressOut,
    ...props
  },
  ref,
) {
  const filter =
    selectedProp !== undefined || defaultSelected !== undefined || onSelectedChange !== undefined
  const [selected, setSelected] = useControllableState({
    value: selectedProp,
    defaultValue: defaultSelected ?? false,
    onChange: onSelectedChange,
  })
  const on = filter && selected
  const color: LabelColor = on ? 'secondaryForeground' : 'foreground'
  const leading = on ? <CheckIcon /> : icon
  const pressable = filter || onPress !== undefined
  const ripple = useRipple({ color, disabled: disabled || !pressable, onPressIn, onPressOut })
  const removeRipple = useRipple({
    color: 'mutedForeground',
    disabled: disabled || !onRemove || filter,
  })

  // An input chip is a group: its text plus a separate remove button, so the
  // remove action has its own name and focus stop.
  if (onRemove && !filter) {
    const name = removeLabel ?? (typeof children === 'string' ? `Remove ${children}` : 'Remove')
    return (
      <ChipFrame ref={ref} paddingRight="1" {...props} {...ripple.props} disabled={disabled}>
        <IconDefaults size={18} color="mutedForeground">
          {icon}
        </IconDefaults>
        <Label color="foreground">{children}</Label>
        <View
          render="button"
          role="button"
          aria-label={name}
          alignItems="center"
          justifyContent="center"
          width="6"
          height="6"
          borderRadius="full"
          cursor={disabled ? 'not-allowed' : 'pointer'}
          backgroundColor={flatValue(
            isWeb && 'transparent',
            !disabled && 'hover:accent',
            !disabled && !removeRipple.active && 'press:accentHover',
          )}
          outlineColor="focus-visible:ring"
          outlineStyle="focus-visible:solid"
          outlineWidth="focus-visible:2px"
          {...(isWeb
            ? { type: 'button', padding: 0, borderWidth: 0 }
            : { accessible: true, hitSlop: 10 })}
          {...removeRipple.props}
          aria-disabled={ariaState(disabled)}
          onPress={() => !disabled && onRemove()}
        >
          {removeRipple.element}
          <XIcon size={14} color="mutedForeground" />
        </View>
      </ChipFrame>
    )
  }

  const semantics = !pressable
    ? {}
    : isWeb
      ? {
          render: 'button' as const,
          type: 'button',
          tabIndex: 0,
          'aria-pressed': filter ? on : undefined,
        }
      : filter
        ? {
            // React Native has no aria-pressed; a toggle button reports "checked".
            accessible: true,
            accessibilityRole: 'togglebutton' as const,
            accessibilityState: { checked: on, disabled },
            hitSlop: 6,
          }
        : { accessible: true, role: 'button' as const, hitSlop: 6 }

  return (
    <ChipFrame
      ref={ref}
      interactive={pressable}
      selected={on}
      disabled={disabled}
      aria-disabled={ariaState(disabled)}
      {...semantics}
      onPress={
        pressable
          ? (event) => {
              if (disabled) return
              onPress?.(event)
              if (filter) setSelected(!selected)
            }
          : undefined
      }
      {...(ripple.active && {
        backgroundColor: on ? 'press:secondary' : 'press:transparent',
        // The ripple is clipped inside the border; a selected chip's border
        // matches its fill, so drop it and let the ripple reach the edge.
        ...(on && { borderWidth: 0 }),
      })}
      {...props}
      {...ripple.props}
    >
      {ripple.element}
      <IconDefaults size={18} color={on ? 'secondaryForeground' : 'mutedForeground'}>
        {leading}
      </IconDefaults>
      <Label color={color}>{children}</Label>
    </ChipFrame>
  )
})

